using System;
using System.Collections.Generic;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using BotPlusAutocadTool.Infrastructure;

namespace BotPlusAutocadTool.UI
{
    /// <summary>
    /// Command icons embedded as WPF resources in two variants, Resources/Icons/Dark and Resources/Icons/Light,
    /// generated by scripts/Build-Icons.ps1. The variant follows the AutoCAD COLORTHEME system variable.
    /// </summary>
    internal static class CommandIcons
    {
        /// <summary>Changes whenever the icon artwork changes; keys the classic toolbar bitmap cache on disk.</summary>
        internal const string ArtworkVersion = "1.10";

        private static readonly string AssemblyName = typeof(CommandIcons).Assembly.GetName().Name;
        private static readonly Dictionary<string, ImageSource> Cache = new(StringComparer.OrdinalIgnoreCase);

        public static string ThemeName(bool dark) => dark ? "Dark" : "Light";

        public static Uri PackUri(string icon, bool dark) =>
            new Uri($"pack://application:,,,/{AssemblyName};component/Resources/Icons/{ThemeName(dark)}/{icon}", UriKind.Absolute);

        /// <summary>Frozen image for the current theme, or null when the resource cannot be decoded.</summary>
        public static ImageSource Get(string icon, bool dark)
        {
            string key = ThemeName(dark) + "/" + icon;
            if (Cache.TryGetValue(key, out var cached)) return cached;
            ImageSource image = null;
            try
            {
                var bitmap = new BitmapImage();
                bitmap.BeginInit();
                bitmap.UriSource = PackUri(icon, dark);
                bitmap.CacheOption = BitmapCacheOption.OnLoad;
                bitmap.EndInit();
                bitmap.Freeze();
                image = bitmap;
            }
            catch (Exception ex) when (ex is System.IO.IOException || ex is NotSupportedException || ex is UriFormatException)
            {
                PluginLog.Error("Command icon " + key, ex);
            }
            Cache[key] = image;
            return image;
        }
    }
}
